window.installParcelOwners=({map,esc,enabled})=>{
const toggle=document.getElementById('owner-lookup');
const countyUrl='https://gisagocss.state.mi.us/arcgis/rest/services/OpenData/michigan_geographic_framework/MapServer/0';
let request,serial=0,highlight,popup;
function clear(){serial++;request?.abort();if(highlight){map.removeLayer(highlight);highlight=null;}if(popup){map.closePopup(popup);popup=null;}}
toggle.addEventListener('change',clear);
map.on('layerremove',()=>{if(!enabled())clear();});
map.on('zoomend',()=>{if(map.getZoom()<15)clear();});
map.on('popupclose',event=>{if(event.popup===popup){serial++;request?.abort();popup=null;if(highlight){map.removeLayer(highlight);highlight=null;}}});
async function query(url,params,signal){const r=await fetch(url+'/query?'+new URLSearchParams(params),{signal});if(!r.ok)throw Error('Service unavailable');const j=await r.json();if(j.error)throw Error('Service unavailable');return j;}
map.on('click',async event=>{
if(!toggle.checked||!enabled()||map.getZoom()<15)return;
clear();const ticket=serial;request=new AbortController();const controller=request;const timeout=setTimeout(()=>controller.abort(),20000);
popup=L.popup({maxWidth:340,maxHeight:330,autoPanPaddingTopLeft:[55,90],autoPanPaddingBottomRight:[20,35]}).setLatLng(event.latlng).setContent('<h3>Parcel owner</h3><p>Finding county and property record…</p>').openOn(map);const currentPopup=popup;
const valid=()=>ticket===serial&&popup===currentPopup&&map.hasLayer(currentPopup);
const geometry=JSON.stringify({x:event.latlng.lng,y:event.latlng.lat,spatialReference:{wkid:4326}});
const spatial={geometry,geometryType:'esriGeometryPoint',inSR:'4326',spatialRel:'esriSpatialRelIntersects'};
let county,recordsLink;
try{
 const counties=await query(countyUrl,{...spatial,f:'json',outFields:'NAME',returnGeometry:'false'},controller.signal);if(!valid())return;
 county=counties.features?.[0]?.attributes?.NAME;
 if(!county){currentPopup.setContent('<h3>Parcel owner</h3><p>No Michigan county found at this point. Tap inside a land parcel.</p>');return;}
 const source=window.OWNER_SOURCES[county];recordsLink=window.COUNTY_RECORDS[county];
 const records=recordsLink?`<a href="${esc(recordsLink)}" target="_blank" rel="noopener">${esc(county)} County property records ↗</a>`:'';
 if(!source){currentPopup.setContent(`<h3>${esc(county)} County</h3><p>Owner names are not connected for this county. Statewide parcel outlines remain available.</p>${records}`);return;}
 currentPopup.setContent(`<h3>${esc(county)} County</h3><p>Looking up recorded owner…</p>`);
 const fields=[...new Set([...source.owner,source.parcel,...source.address,source.acres])];
 const result=await query(source.url,{...spatial,f:'geojson',outFields:fields.join(','),returnGeometry:'true',outSR:'4326',resultRecordCount:'10'},controller.signal);if(!valid())return;
 const features=result.features||[];
 if(!features.length){currentPopup.setContent(`<h3>${esc(county)} County</h3><p>No matching county parcel record at this point. Tap farther inside the parcel. County and statewide boundaries may differ.</p>${records}`);return;}
 const names=p=>[...new Set(source.owner.map(k=>p[k]).filter(v=>v&&String(v).trim()).map(v=>String(v).trim()))];
 const blocks=features.map(f=>{const p=f.properties||{},owner=names(p);return `<section class="owner-result"><h4>${owner.length?owner.map(esc).join('<br>'):'Owner name not provided by source'}</h4><p><b>Parcel:</b> ${esc(p[source.parcel]||'Not provided')}</p><p>${esc(source.address.map(k=>p[k]).filter(Boolean).join(' '))}</p>${p[source.acres]!=null?`<p><b>Recorded acreage:</b> ${esc(p[source.acres])}</p>`:''}</section>`;}).join('<hr>');
 highlight=L.geoJSON(features,{interactive:false,style:{color:'#e7a529',weight:3,fillOpacity:.1}}).addTo(map);
 if(features.length===1){const owner=names(features[0].properties||{});if(owner.length)highlight.bindTooltip(owner.map(esc).join(' / '),{permanent:true,direction:'center',className:'parcel-owner-label'});}
 currentPopup.setContent(`<h3>${esc(county)} County · recorded owner</h3>${blocks}${features.length>=10?'<p>Showing up to 10 overlapping records; consult county records for others.</p>':''}<p><small>${esc(source.vintage)} Ownership does not grant access permission.</small></p>${records}<a href="${esc(source.url)}" target="_blank" rel="noopener">GIS source ↗</a>`);
}catch(error){if(valid())currentPopup.setContent(`<h3>Owner lookup unavailable</h3><p>The county service did not respond. Tap again to retry.</p>${recordsLink?`<a href="${esc(recordsLink)}" target="_blank" rel="noopener">County property records ↗</a>`:''}`);}finally{clearTimeout(timeout);}
});
};
